    const disc = (r, c, ring = INK.BK) => { ctx.beginPath(); ctx.arc(0, 0, r + 2, 0, 7); ctx.fillStyle = ring; ctx.fill(); ctx.beginPath(); ctx.arc(0, 0, r, 0, 7); ctx.fillStyle = c; ctx.fill(); };
    blip(POI.tower, () => { disc(9, INK.CR); block(ctx, [[-2.5, 6], [-2.5, -2], [0, -7], [2.5, -2], [2.5, 6]], INK.BK); });         // the Martinitoren
    blip(POI.station, () => { disc(8, INK.CR); ctx.fillStyle = INK.BK; ctx.fillRect(-5, -1, 10, 2); ctx.fillRect(-5, -5, 10, 2); ctx.fillRect(-5, 3, 10, 2); });   // trains
