    for (let ty = 0; ty < H; ty += FH) for (let tx = 0; tx < W; tx += FW) { draw(tile, { x: X0 + (tx + FW / 2) / s, y: Y0 + (ty + FH / 2) / s, s }, { baseOnly: true }); c.drawImage(tile.canvas, tx, ty); }
