    ctx.lineTo(tx - 1 * s - wind * 24 * s, sy + (wind ? 8 : 18) * s + flap); ctx.quadraticCurveTo(tx - 4 * s - wind * 10 * s, sy + 10 * s, tx + 4 * s, sy + 5 * s); ctx.closePath(); ctx.fill();
