    const mc = kind === 'poster' ? BK : CR; ln(.08, .08, .92, .08, mc); ln(.92, .08, .92, .92, mc); ln(.92, .92, .08, .92, mc); ln(.08, .92, .08, .08, mc);   // the mount
    if (kind === 'tower') { ln(.5, .15, .5, .85, CR, 3); ln(.4, .15, .4, .6, CR, 1.4); ln(.6, .15, .6, .6, CR, 1.4); ln(.44, .72, .56, .72, CR, 1.4); ln(.5, .85, .5, .9, RD, 2); ln(.1, .15, .9, .15, CR, 1); }
    if (kind === 'poster') { ln(.2, .75, .45, .75, RD, 6); ln(.25, .62, .4, .62, RD, 5); ln(.62, .8, .74, .7, RD, 7); ln(.15, .34, .85, .34, BK, 6); ln(.15, .18, .7, .18, BK, 6); ln(.1, .9, .9, .9, BK, 1.2); }
