  { const fx = x => L2 + (x - e2[0]) / RUN * RISE; picture([[-2.6, fx(-2.6) + 1.25, 4.01], [-2.0, fx(-2.0) + 1.25, 4.01], [-2.0, fx(-2.0) + 1.85, 4.01], [-2.6, fx(-2.6) + 1.85, 4.01]], 'tower'); }
