    const tick = () => { if (done) return; const t = now(); if (t >= TL.end) return end(); const fi = Math.floor(t * FILM_FPS); if (fi !== lastF) { lastF = fi; frame(M, Math.max(0, fi / FILM_FPS)); } raf = requestAnimationFrame(tick); };
